CLAUDE_BIN = 'claude'   #: the binary the SDK spawns, overridden per chat with `bin=`
opus5    = 'claude-opus-5'
opus48   = 'claude-opus-4-8'
sonnet5  = 'claude-sonnet-5'
sonnet46 = 'claude-sonnet-4-6'
haiku45  = 'claude-haiku-4-5'
fable5   = 'claude-fable-5'

#: Every id above, for anything that wants to offer the list rather than reach for one of them.
CLAUDE_MODELS = {'opus5': opus5, 'opus48': opus48, 'sonnet5': sonnet5, 'sonnet46': sonnet46,
                 'haiku45': haiku45, 'fable5': fable5}

#: The CLI's own tier aliases. Each names the latest model of its tier on your plan, so a chat that
#: asks for one survives a model refresh with no release here. `CLAUDE_MODELS` is the other
#: direction: a pinned id, for a conversation that must not move under you.
CLAUDE_ALIASES = ('opus', 'sonnet', 'haiku', 'fable')
CLAUDE_ENTRYPOINT = 'sdk-py'    #: what a record rishi filed says it came from. See `prune_sessions`
CLAUDE_DISALLOWED = ('Bash', 'Write', 'Edit', 'NotebookEdit')
CLAUDE_SERVER_TOOLS = ('WebSearch', 'WebFetch')  #: Claude Code's own, run on its side and never in rishi's tool loop
CLAUDE_WORK_DIR = Path.home()/'.rishi-claude'    #: where a conversation is filed, outside any real project
MAX_BUFFER = 10*2**20                            #: the SDK's stdout cap. Its own default is 1MB, and it raises rather than truncating

def claude_bin(bin=CLAUDE_BIN):
    "Absolute path to the `claude` binary, or a `FileNotFoundError` that says how to get one."
    if (p := shutil.which(bin)): return p
    raise FileNotFoundError(
        f'{bin!r} is not on $PATH. Install Claude Code (https://claude.com/claude-code) and run '
        f'`{bin} /login`. rishi drives it as a subprocess and never reads your credentials.')

def claude_model(model=None, dflt=opus5):
    """A name Claude Code takes: a `CLAUDE_MODELS` key resolved to its id, anything else as it is.

    So `'opus5'`, `'claude-opus-5'` and the CLI's own `'opus'` all reach `--model`, and an id rishi
    has never heard of is passed through rather than second-guessed here.
    """
    m = (model or '').strip()
    return CLAUDE_MODELS.get(m, m) if m else dflt

def claude_fallback(models):
    "Models for `--fallback-model`, resolved as `claude_model` does, in the order they are tried."
    ms = models.split(',') if isinstance(models, str) else listify(models)
    return ','.join(x for m in ms if (x := claude_model(m, dflt='')))

_cc_version = {}
def claude_version(bin=CLAUDE_BIN):
    "The installed Claude Code's version, cached per binary, for the `version` a record carries."
    if bin not in _cc_version:
        try: out = subprocess.run([claude_bin(bin), '--version'], capture_output=True, text=True, timeout=30).stdout
        except Exception: out = ''
        m = re.search(r'\d+\.\d+\.\d+', out)
        _cc_version[bin] = m.group(0) if m else ant.CC_VERSION
    return _cc_version[bin]

def sess_entrypoint(p, mx=50):
    """What a transcript says wrote it, or None.

    Claude Code writes its own bookkeeping first: `queue-operation` and `mode` records sit ahead of
    the session header, so the first line does not carry `entrypoint` and reading only that line
    read every transcript as somebody else's.
    """
    try:
        with p.open() as f:
            for i, l in enumerate(f):
                if i >= mx: return None
                try: rec = json.loads(l)
                except Exception: continue
                if (e := rec.get('entrypoint')): return e
    except OSError: return None
    return None

def prune_sessions(cwd=None, keep=0, age=None, entrypoint=CLAUDE_ENTRYPOINT):
    "Delete filed transcripts under `cwd`, sparing the newest `keep`, and return what went."
    d = ant.sess_dir(cwd or CLAUDE_WORK_DIR)
    if not d.is_dir(): return []
    fs = sorted(d.glob('*.jsonl'), key=lambda p: p.stat().st_mtime, reverse=True)
    out, now = [], time.time()
    for p in fs[keep:]:
        if age is not None and now - p.stat().st_mtime < age: continue
        if sess_entrypoint(p) != entrypoint: continue
        p.unlink(missing_ok=True)
        out.append(p)
    return out


def norm_claude_usage(u, model=None, cost=None):
    "Claude Code's usage block -> rishi's, so a Claude turn adds up with a local one."
    if not u: return {}
    read, made = u.get('cache_read_input_tokens') or 0, u.get('cache_creation_input_tokens') or 0
    pt, ct = (u.get('input_tokens') or 0) + read + made, u.get('output_tokens') or 0
    return {'prompt_tokens': pt, 'completion_tokens': ct, 'total_tokens': pt + ct, 'cached_tokens': read,
            'cache_creation_tokens': made, 'cost': cost or 0.0, 'model': model}

ABORTED = ('aborted_streaming', 'aborted')
_status_re = re.compile(r'\b(\d{3})\b')

class ClaudeError(RuntimeError):
    "A failed Claude Code turn: what it said, the status behind it, and the raw result."
    def __init__(self, msg, status=None, raw=None):
        self.status, self.raw = status, raw
        super().__init__(msg)

def claude_status(d):
    "The HTTP status behind a failed result: what Claude Code reported, else one read out of the text."
    if (s := d.get('api_error_status')):
        try: return int(s)
        except (TypeError, ValueError): pass
    m = _status_re.search(f"{d.get('result') or ''} {d.get('subtype') or ''}")
    return int(m.group(1)) if m else None

def norm_claude(d, model=None):
    "A Claude Code result -> a rishi `Resp`, with `<tool_call>` tags read out of the text."
    if d.get('is_error') and d.get('terminal_reason') not in ABORTED:
        raise ClaudeError(f"claude failed: {d.get('result') or d.get('subtype')}",
                          status=claude_status(d), raw=d)
    text, th = split_think(d.get('result') or '')
    text, tcs = parse_tool_tags(text)
    res = {'role': 'assistant', 'content': text}
    if th: res['channels'] = {'thought': th}
    if tcs: res['tool_calls'] = tcs
    res['usage'] = norm_claude_usage(d.get('usage'), model, d.get('cost'))
    return Resp(res)
