@patch
def _file_sess(self:ClaudeChat, hist=None):
    "File `hist` as a resumable Claude Code transcript, returning its session id, or None if empty."
    if not self.transcript: return None
    msgs = anth_msgs(ifnone(hist, self.hist), ant)
    if not msgs: return None
    cwd = self._cwd
    cwd.mkdir(parents=True, exist_ok=True)
    sid = ant.stable_uuid(f'rishi-claude:{self._nonce}:{ant.canon(msgs)}')
    recs = ant.msgs2recs(msgs, key=sid, cwd=cwd, model=self.model_id, entrypoint=CLAUDE_ENTRYPOINT,
                         version=claude_version(self.bin))
    for r in recs:
        c = r['message']['content']
        # An assistant record's content must be a list: Claude Code calls `.some()` on it. The `ant`
        # rishi depends on already writes one; this stands so a change there cannot break a resume.
        if r['type'] == 'assistant' and isinstance(c, str): r['message']['content'] = [{'type': 'text', 'text': c}]
    ant.save_sess(recs, sid, cwd)
    self._note_filed(ant.sess_file(sid, cwd))
    return sid

@patch
def _note_filed(self:ClaudeChat, p):
    "Remember a transcript this chat wrote, and with `cleanup` drop the one it replaces."
    p = Path(p)
    if p in self._filed: return p             # refiled, not replaced: the same history, the same file
    if self.cleanup: self._sweep(keep=p)      # one chat, one transcript on disk
    self._filed.append(p)
    return p

@patch
def _sweep(self:ClaudeChat, keep=None):
    "Remove the transcripts this chat filed, except `keep`, and return what went."
    out = []
    for p in list(getattr(self, '_filed', None) or []):
        if p == keep: continue
        try: p.unlink(missing_ok=True)
        except OSError: continue
        self._filed.remove(p)
        out.append(p)
    return out

@patch
def _split_turn(self:ClaudeChat):
    "What to file and what to send: `(past, prompt)`."
    if self.hist and self.hist[-1].get('role') == 'tool': return self.hist, CONT_PROMPT
    return self.hist[:-1], self._as_turn(self.hist[-1:])

@patch
def _as_turn(self:ClaudeChat, msgs):
    "`msgs` as one prompt: the text itself for a lone user turn, headed prose for several, blocks for media."
    if any(is_media(p) for m in msgs for p in (m.get('content') or []) if isinstance(p, dict)):
        from aidialog.msg_parts import Msg
        from fastllm.anthropic import denorm_user
        return denorm_user(Msg(role='user', content=self._to_parts(msgs)))['content']
    if len(msgs) == 1 and msgs[0].get('role') == 'user' and not msgs[0].get('tool_calls'):
        return resp_text(msgs[0])            # a real user turn, with no role heading to read past
    return render_prompt(msgs)

